effect.shader:
float hash11(float x) { return fract(sin(x * 127.1) * 43758.5453); }

void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    vec2 p = acScreenNorm - center;
    p.x *= acAspect;
    float r = length(p);
    if (r < inner) { fragColor = orig; return; }

    float ang = atan(p.y, p.x);
    float fatia = floor(ang / (6.2831853 / density));
    float semente = hash11(fatia * 7.1);
    float t = fract(semente + acTime * speed * (0.5 + semente));
    // o fim da linha fica no raio = length * t (fora do inner)
    float ponta = inner + (reach - inner) * t;
    float d = abs(r - ponta);
    float traco = smoothstep(0.02, 0.0, d) * smoothstep(inner, inner + 0.1, r) * (1.0 - t);

    vec3 cor = orig.rgb + tint.rgb * tint.a * traco * 1.5;
    fragColor = vec4(cor, orig.a);
}
